<script>
import Loading from '@shell/components/Loading';
import { Banner } from '@components/Banner';
import CreateEditView from '@shell/mixins/create-edit-view';
import LabeledSelect from '@shell/components/form/LabeledSelect';
import { LabeledInput } from '@components/Form/LabeledInput';
import { Checkbox } from '@components/Form/Checkbox';
import { NORMAN, SECRET } from '@shell/config/types';
import { stringify } from '@shell/utils/error';
import { _VIEW } from '@shell/config/query-params';
import { PveApi } from '../pve.ts';
import {
  FS_OPTIONS, emptyRow, parseRow, rowError, rowsError, serializeRow,
} from '../disk-spec.ts';
import {
  IP_MODES, prefixError, ipStartError, ipEndError, poolError, gatewayError,
  nameserversError, requiredFieldsError, dnsCloudInitError, poolCapacity, vmidRangeError,
} from '../ip-config';
import {
  TEMPLATE_MATCHES, discoveredTags, templateTagError,
} from '../template-select.ts';
import {
  cicustomError, emptyRow as emptyExtraRow, parseRow as parseExtraRow,
  reservedKeys, rowError as extraRowErrorFor, rowsError as extraRowsError,
  serializeRow as serializeExtraRow,
} from '../extra-config.ts';

/** Disk formats PVE accepts for a full clone; empty takes the storage default. */
const CLONE_FORMATS = ['raw', 'qcow2', 'vmdk'];

function initOptions() {
  return {
    options:  [],
    selected: null,
    busy:     false,
    enabled:  false,
  };
}

export default {
  components: {
    Banner, Checkbox, Loading, LabeledInput, LabeledSelect,
  },

  mixins: [CreateEditView],

  props: {
    uuid: {
      type:     String,
      required: true,
    },

    cluster: {
      type:    Object,
      default: () => ({})
    },

    credentialId: {
      type:     String,
      required: true,
    },

    disabled: {
      type:    Boolean,
      default: false
    },

    busy: {
      type:    Boolean,
      default: false
    },

    provider: {
      type:     String,
      required: true,
    }
  },

  async fetch() {
    this.errors = [];
    this.diskRows = (this.value?.dataDisk || []).map((entry) => parseRow(entry));
    this.extraRows = (this.value?.extraConfig || []).map((entry) => parseExtraRow(entry));

    // Seed the addressing defaults here rather than only in `test()`, so the
    // dropdown shows DHCP as soon as the form opens instead of blank. A blank
    // select reads as "no default" and invites the user to leave it unset.
    if (this.value && !this.value.ipMode) {
      this.value.ipMode = 'dhcp';
    }

    // A stored pool tells us which selection mode it was saved with: the two
    // are mutually exclusive in the driver, so a tag present means tag mode.
    this.templateSource = this.value?.templateTag ? 'tag' : 'vmid';

    if (this.value && !this.value.templateTagMatch) {
      this.value.templateTagMatch = 'subset';
    }

    // Seeded so the checkbox renders ticked on a new pool rather than relying
    // on the getter's fallback, which would leave the stored config empty and
    // therefore at the mercy of whatever the template set.
    if (this.value && !this.value.backup) {
      this.value.backup = 'true';
    }

    // Cloud-init is mandatory: it is the only channel carrying the SSH key the
    // driver and Rancher's system-agent both need, plus ipconfig0 and DNS. The
    // driver forces it on regardless, so keep the stored config honest instead
    // of letting a pool claim it is off.
    if (this.value) {
      this.value.cloudinit = true;
    }

    if ( !this.credentialId ) {
      return;
    }

    if (this.mode === _VIEW) {
      this.fakeSelectOptions(this.nodes, this.value?.node);
      this.fakeSelectOptions(this.templates, this.value?.templateVmid);
      this.fakeSelectOptions(this.bridges, this.value?.netBridge);

      return;
    }

    try {
      this.credential = await this.$store.dispatch('rancher/find', { type: NORMAN.CLOUD_CREDENTIAL, id: this.credentialId });
    } catch (e) {
      this.credential = null;
    }

    // Cloud credentials hand the driver only the secret value; PVE stores the
    // full token as `USER@REALM!TOKENID=SECRET` in the apiTokenSecret field,
    // so we read it back from the backing Secret to reconstruct the header.
    let api = null;

    try {
      const id = this.credentialId.replace(':', '/');
      const secret = await this.$store.dispatch('management/find', { type: SECRET, id });
      const data = secret.data['pvecredentialConfig-apiTokenSecret'];
      const secretValue = atob(data);

      api = new PveApi(this.$store, {
        apiUrl:    atob(secret.data['pvecredentialConfig-apiUrl'] || ''),
        apiToken:  `${ atob(secret.data['pvecredentialConfig-apiTokenId'] || '') }=${ secretValue }`,
      });
    } catch (e) {
      console.error(e); // eslint-disable-line no-console
      this.errors.push('Unable to read the cloud credential secret');

      return;
    }

    this.api = api;
    this.ready = true;
    this.authenticating = true;

    // Kick off node list load; subsequent dropdowns chain off the selected node.
    const res = await this.api.getNodes();

    this.authenticating = false;

    if (res.error) {
      // The PVE API is not reachable through Rancher's /meta/proxy — typically
      // because the Rancher server does not trust the PVE certificate, which the
      // proxy always verifies and cannot be told to skip. The driver itself does
      // not use this proxy, so provisioning still works; fall back to typing the
      // four discovered fields by hand instead of blocking the form. The cloud
      // credential surfaces the same condition as a warning.
      this.degraded = true;
      this.errors.push(this.t('driver.pve.machine.errors.unreachable'));
      this.emitDegradedValidation();

      return;
    }

    this.nodes.options = res.map((n) => ({ label: n.node, value: n.node }));
    this.nodes.busy = false;
    this.nodes.enabled = true;
    this.nodes.selected = this.value?.node || this.nodes.options[0]?.value;

    if (this.nodes.selected) {
      await this.loadNodeSpecific(this.nodes.selected);
    }

    // Not an unconditional `true`: a pool reopened with a tag that no longer
    // matches any template must come up invalid, and the template list it is
    // checked against has only just loaded.
    this.emitValidation();
  },

  data() {
    return {
      authenticating:  false,
      ready:           false,
      // True when the PVE API could not be reached: the dropdowns are replaced
      // by free-text inputs bound straight to the machine config.
      degraded:        false,
      api:             null,
      credential:      null,
      nodes:           initOptions(),
      templates:       initOptions(),
      // Raw PVE template objects behind templates.options, kept because tag
      // matching needs their `tags` field, which the option list drops.
      templateList:    [],
      storage:         initOptions(),
      bridges:         initOptions(),
      errors:          null,
      diskRows:        [],
      extraRows:       [],
      ipModes:         IP_MODES,
      // How the template is named: by VMID (the dropdown) or by a tag it
      // carries. Tag selection lets a rebuilt image be rolled out by moving
      // the tag in PVE, with no edit to this pool.
      templateSource:  'vmid',
    };
  },

  watch: {
    'credentialId'() {
      this.$fetch();
    },

    'nodes.selected'(node) {
      if (node) {
        this.loadNodeSpecific(node);
      }
    },

    // In degraded mode the two required fields are typed rather than picked, so
    // validity has to be re-reported as they change.
    'value.node'() {
      this.emitDegradedValidation();
    },

    'value.templateVmid'() {
      this.emitDegradedValidation();
    },

    'value.templateTag'() {
      this.emitValidation();
    },

    'value.templateTagMatch'() {
      this.emitValidation();
    },

    templateSource() {
      this.emitValidation();
    },

    // Storage and format are full-clone-only: PVE rejects them on a linked
    // clone, whose disk is an overlay on the template's own. Clear them as
    // the box is ticked rather than letting a rejected pool be saved.
    'value.linkedClone'(linked) {
      if (linked) {
        this.value.cloneStorage = '';
        this.value.cloneFormat = '';
      }
      this.emitValidation();
    },

    // A row with an invalid size, storage or mount path must block saving: the
    // driver would reject the same value in PreCreateCheck, but only after the
    // pool has already been created.
    'value.cloudinit'() {
      this.emitValidation();
    },

    // Same reasoning for the addressing fields: an unusable base, gateway or
    // span must block the save, so validity has to be re-reported as they
    // change rather than waiting for the first machine to fail provisioning.
    'value.ipMode'() {
      this.emitValidation();
    },

    'value.ipStart'() {
      this.emitValidation();
    },

    'value.ipEnd'() {
      this.emitValidation();
    },

    'value.ipPrefix'() {
      this.emitValidation();
    },

    'value.gateway'() {
      this.emitValidation();
    },

    'value.nameservers'() {
      this.emitValidation();
    },

    'value.searchdomain'() {
      this.emitValidation();
    },

    'value.vmidRange'() {
      this.emitValidation();
    },

    diskRows: {
      deep: true,
      handler() {
        this.emitValidation();
      },
    },

    extraRows: {
      deep: true,
      handler() {
        this.emitValidation();
      },
    },

    'value.cicustom'() {
      this.emitValidation();
    },
  },

  computed: {
    /**
     * The pve-net-* knobs are only written while rewriting the NIC, which the
     * driver only does when a bridge is named — it rejects the pool otherwise.
     * Mirror that here so the fields cannot be filled in uselessly.
     */
    netOptionsEnabled() {
      return this.degraded ? !!this.value?.netBridge : !!this.bridges.selected;
    },

    /**
     * Tri-state: empty means "leave PVE's own default alone", which a checkbox
     * cannot express and which the driver treats as distinct from false.
     */
    firewallOptions() {
      return [
        { label: this.t('driver.pve.machine.firewall.default'), value: '' },
        { label: this.t('driver.pve.machine.firewall.enabled'), value: 'true' },
        { label: this.t('driver.pve.machine.firewall.disabled'), value: 'false' },
      ];
    },

    /** True when any data disk asks for a filesystem, which requires cloud-init. */
    needsCloudInit() {
      return this.diskRows.some((row) => row.fs !== 'none');
    },

    /**
     * The VM User drives both the cloud-init account and the SSH login, so they
     * can no longer disagree. What remains is the `root` default, which neither
     * documented template permits (Debian uses `debian`, Leap Micro `rancher`)
     * and which surfaces only as a node that provisions and never reaches Ready.
     * A warning, not an error: an image with a root login is legitimate.
     */
    sshUserWarning() {
      return (this.value?.sshUser || '').trim() === 'root'
        ? this.t('driver.pve.machine.warnings.sshUserRoot')
        : '';
    },

    /**
     * The driver's `backup` is tri-state (empty keeps the template's setting),
     * because an unset boolean would be indistinguishable from an explicit
     * "exclude" and would drop every pre-existing pool out of its backup job.
     * The form only offers the two deliberate states, defaulting to included —
     * which is also PVE's own default for a disk.
     */
    backupEnabled: {
      get() {
        return this.value?.backup !== 'false';
      },
      set(on) {
        this.value.backup = on ? 'true' : 'false';
      },
    },

    /** Cross-row problems the per-row validator cannot see. */
    diskRowsCrossError() {
      return rowsError(this.diskRows);
    },

    /**
     * Recomputed rather than fixed, because which keys the driver claims depends
     * on the rest of the form: with no bridge set it never touches the NIC, so
     * defining net0 here is legitimate.
     */
    extraReserved() {
      return reservedKeys({
        ...this.value,
        netBridge: this.degraded ? this.value?.netBridge : this.bridges.selected,
      });
    },

    extraRowsCrossError() {
      return extraRowsError(this.extraRows);
    },

    cicustomErr() {
      return cicustomError(this.value?.cicustom, this.isStaticIP);
    },

    /**
     * "none" is the driver's flag value; the label says what it actually does,
     * since "none" reads like "do not attach a disk" rather than "attach it
     * unformatted".
     */
    fsOptions() {
      return FS_OPTIONS.map((fs) => ({
        label: this.t(`driver.pve.machine.fs.${ fs }`),
        value: fs,
      }));
    },

    /** True while the template is being named by tag rather than by VMID. */
    byTag() {
      return this.templateSource === 'tag';
    },

    templateSourceOptions() {
      return [
        { label: this.t('driver.pve.machine.templateSources.vmid'), value: 'vmid' },
        { label: this.t('driver.pve.machine.templateSources.tag'), value: 'tag' },
      ];
    },

    templateMatchOptions() {
      return TEMPLATE_MATCHES.map((m) => ({
        label: this.t(`driver.pve.machine.templateMatches.${ m }`),
        value: m,
      }));
    },

    /** Tags seen on the discovered templates, offered as suggestions. */
    templateTagOptions() {
      return discoveredTags(this.templateList).map((tag) => ({ label: tag, value: tag }));
    },

    /**
     * Mirrors the driver's resolution: exactly one template must carry the
     * tag, or provisioning fails. Checking it here turns "the machine pool
     * saved and then every machine failed" into an error on the field.
     *
     * In degraded mode there is no template list to check against, so this
     * falls back to validating the tag's format only.
     */
    templateTagErr() {
      if (!this.byTag) {
        return '';
      }

      return templateTagError(
        this.value?.templateTag || '',
        this.value?.templateTagMatch || 'subset',
        this.degraded ? null : this.templateList,
      );
    },

    /** Storage and disk format are full-clone-only in PVE. */
    cloneTargetEnabled() {
      return !this.value?.linkedClone;
    },

    /**
     * HA needs somewhere to fail over to, so the fields stay hidden on a
     * single-node install, where PVE rejects the registration outright.
     *
     * Gated on the loaded node list rather than on how many nodes the pool
     * allows: a pool pinned to one node is still a legitimate HA user — the
     * point is that HA moves the VM elsewhere when that node dies.
     */
    haAvailable() {
      return this.nodes.options.length > 1;
    },

    cloneFormatOptions() {
      return [
        { label: this.t('driver.pve.machine.cloneFormats.default'), value: '' },
        ...CLONE_FORMATS.map((f) => ({ label: f, value: f })),
      ];
    },

    /** Empty means "the template's own storage", which is PVE's own default. */
    cloneStorageOptions() {
      return [
        { label: this.t('driver.pve.machine.cloneStorage.default'), value: '' },
        ...this.storage.options,
      ];
    },

    isStaticIP() {
      return this.value?.ipMode === 'static';
    },

    ipStartErr() {
      return this.isStaticIP ? ipStartError(this.value?.ipStart || '') : '';
    },

    ipEndErr() {
      return this.isStaticIP ? ipEndError(this.value?.ipEnd || '', this.value?.ipStart || '') : '';
    },

    ipPrefixErr() {
      return this.isStaticIP ? prefixError(this.value?.ipPrefix || '') : '';
    },

    /** Cross-field checks: both ends in one subnet, no network/broadcast. */
    ipPoolErr() {
      return this.isStaticIP ? poolError(this.value?.ipStart || '', this.value?.ipEnd || '', this.value?.ipPrefix || '') : '';
    },

    gatewayErr() {
      return this.isStaticIP ? gatewayError(this.value?.gateway || '', this.value?.ipStart || '', this.value?.ipPrefix || '') : '';
    },

    nameserversErr() {
      return nameserversError(this.value?.nameservers || '');
    },

    /**
     * The subnet caps how many machines the pool can hold, not the VMID range.
     * Shown as a hint because it is the number the operator needs when sizing a
     * pool, and getting it wrong otherwise only shows up as a machine that
     * fails to provision.
     */
    poolCapacityHint() {
      if (!this.isStaticIP) {
        return '';
      }
      const n = poolCapacity(this.value?.ipStart || '', this.value?.ipEnd || '');

      if (n < 1) {
        return '';
      }

      return this.t('driver.pve.machine.hints.poolCapacity', { count: n });
    },

    /** Presence and consistency rules the per-field format checks cannot see. */
    requiredFieldsErr() {
      return requiredFieldsError(
        this.value?.ipMode || '',
        this.value?.ipStart || '',
        this.value?.ipEnd || '',
        this.value?.ipPrefix || '',
        this.value?.gateway || '',
        this.value?.vmidRange || '',
        !!this.value?.cloudinit,
      );
    },

    dnsCloudInitErr() {
      return dnsCloudInitError(this.value?.nameservers || '', this.value?.searchdomain || '', !!this.value?.cloudinit);
    },

    // Format only, independent of addressing mode: an explicit VMID range is
    // usable whether or not addressing is static. Kept out of addressingErrors
    // and shown inline under the field instead, since it lives in the
    // Placement section, nowhere near the addressing errors list.
    vmidRangeErr() {
      return vmidRangeError(this.value?.vmidRange || '');
    },

    addressingErrors() {
      return [
        this.requiredFieldsErr, this.ipStartErr, this.ipEndErr,
        this.ipPrefixErr, this.ipPoolErr, this.gatewayErr,
        this.nameserversErr, this.dnsCloudInitErr,
      ].filter((e) => e !== '');
    },
  },

  methods: {
    stringify,

    /**
     * Node and template are the only fields the driver cannot default, so in
     * degraded mode they decide whether the pool is valid. No-op when the
     * dropdowns loaded normally, where `fetch` already reported validity.
     */
    emitDegradedValidation() {
      if (!this.degraded) {
        return;
      }

      this.$emit('validationChanged', !!this.value?.node && this.templateSelectionValid() && this.diskRowsValid() && this.extraRowsValid() && this.addressingValid() && !this.vmidRangeErr);
    },

    /**
     * The template must be named exactly one way, and the way it is named must
     * be usable. Tag mode is checked against the discovered templates; VMID
     * mode only matters in degraded mode, where the field is typed by hand.
     */
    templateSelectionValid() {
      if (this.byTag) {
        return this.templateTagErr === '';
      }

      return !this.degraded || !!this.value?.templateVmid;
    },

    addDiskRow() {
      this.diskRows.push(emptyRow());
    },

    removeDiskRow(idx) {
      this.diskRows.splice(idx, 1);
    },

    diskRowError(row) {
      return rowError(row);
    },

    /**
     * Every row must be valid before the pool can be saved, and a disk that
     * wants a filesystem needs cloud-init: the driver formats and mounts it
     * over SSH with the key cloud-init injects, and rejects the pool otherwise.
     */
    diskRowsValid() {
      if (this.needsCloudInit && !this.value?.cloudinit) {
        return false;
      }

      if (rowsError(this.diskRows) !== '') {
        return false;
      }

      return this.diskRows.every((row) => rowError(row) === '');
    },

    addExtraRow() {
      this.extraRows.push(emptyExtraRow());
    },

    removeExtraRow(idx) {
      this.extraRows.splice(idx, 1);
    },

    extraRowError(row) {
      return extraRowErrorFor(row, this.extraReserved);
    },

    /**
     * The driver rejects a bad key or a reserved one in PreCreateCheck, which is
     * after the clone: the pool saves, the machine is created, and the config
     * request then fails and rolls it back. Blocking the save is cheaper.
     */
    extraRowsValid() {
      if (this.cicustomErr !== '' || extraRowsError(this.extraRows) !== '') {
        return false;
      }

      return this.extraRows.every((row) => this.extraRowError(row) === '');
    },

    /**
     * Addressing problems must block saving too. The driver rejects the same
     * values in PreCreateCheck, which is far too late: the pool saves cleanly
     * and only the first machine to provision reveals the mistake.
     */
    addressingValid() {
      return this.addressingErrors.length === 0;
    },

    /** The full validity expression, shared by every watcher that re-reports it. */
    emitValidation() {
      this.$emit('validationChanged', this.diskRowsValid() && this.extraRowsValid() && this.addressingValid() && !this.vmidRangeErr && this.templateSelectionValid() && (!this.degraded || !!this.value?.node));
    },

    fakeSelectOptions(list, value) {
      list.busy = false;
      list.enabled = false;
      list.options = [];

      if (value) {
        list.options.push({ label: String(value), value });
      }

      list.selected = value;
    },

    async loadNodeSpecific(node) {
      this.templates.busy = this.storage.busy = this.bridges.busy = true;
      this.templates.enabled = this.storage.enabled = this.bridges.enabled = false;

      const [tmpl, stor, brg] = await Promise.all([
        this.api.getTemplates(node),
        this.api.getStorage(node),
        this.api.getBridges(node),
      ]);

      if (!tmpl.error) {
        // Tag matching needs the whole PVE object (specifically `tags`), which
        // the label/value option list below throws away.
        this.templateList = tmpl.map((o) => o.value);

        // String, not Number: every field in an rke-machine-config CRD is typed
        // as a string, and an integer here is rejected outright on save.
        this.templates.options = tmpl.map((o) => ({
          label: `${ o.value.vmid } (${ o.value.name || 'unnamed' })`,
          value: String(o.value.vmid),
        }));
        this.templates.selected = this.value?.templateVmid || this.templates.options[0]?.value;
        this.templates.enabled = true;
      }

      if (!stor.error) {
        // toOptions() sets `value` to the whole PVE object; the machine config
        // needs the storage id string, so map it down here.
        this.storage.options = stor.map((o) => ({
          label: o.value.storage,
          value: o.value.storage,
        }));
        this.storage.enabled = true;
      }

      if (!brg.error) {
        // Same as storage above: toOptions() sets `value` to the whole PVE
        // object, and binding that produces `netBridge: {...}`, which the CRD
        // rejects with "must be of type string: object".
        this.bridges.options = brg.map((o) => ({
          label: o.value.iface,
          value: o.value.iface,
        }));
        this.bridges.selected = this.value?.netBridge || this.bridges.options[0]?.value;
        this.bridges.enabled = true;
      }

      this.templates.busy = this.storage.busy = this.bridges.busy = false;
    },

    test() {
      // Rows are serialized even in degraded mode: they are typed by hand there
      // too, and unlike the selects they hold real values.
      this.value.dataDisk = this.diskRows.map((row) => serializeRow(row));

      // A row left blank is someone who clicked Add and changed their mind, not
      // a config error — drop it rather than shipping `=` to the driver.
      this.value.extraConfig = this.extraRows
        .filter((row) => (row.key || '').trim())
        .map((row) => serializeExtraRow(row));

      // Default the mode so a pool saved before this field existed keeps its
      // previous DHCP behaviour rather than failing validation. Also seeded in
      // `fetch` so the dropdown is never blank; repeated here because `test`
      // also runs for configs this component never rendered.
      if (!this.value.ipMode) {
        this.value.ipMode = 'dhcp';
      }

      // Mandatory, see `fetch`. Re-asserted here so a stored config can never
      // ship with it off.
      this.value.cloudinit = true;

      // Same as `fetch`, for a config this component never rendered.
      if (!this.value.backup) {
        this.value.backup = 'true';
      }

      // The driver rejects static fields left over from a mode switch, so clear
      // them rather than shipping a pool it will refuse.
      if (this.value.ipMode !== 'static') {
        this.value.ipStart = '';
        this.value.ipEnd = '';
        this.value.ipPrefix = '';
        this.value.gateway = '';
      }

      // One field drives both: cloud-init installs the SSH keys for `ciuser`,
      // and that is the account Rancher then logs in as. The driver applies the
      // same fallback, so this only keeps the stored config self-consistent.
      this.value.ciuser = this.value.sshUser || '';

      // The driver hard-fails when a VLAN tag, MTU or firewall setting is given
      // without a bridge. Clear them rather than shipping a pool it will reject.
      if (!this.netOptionsEnabled) {
        this.value.netVlanTag = 0;
        this.value.netMtu = 0;
        this.value.netFirewall = '';
      }

      // The driver rejects a pool that names the template both ways, so only
      // the fields of the active mode survive. Clearing the other side also
      // keeps a pool that switched modes from carrying a stale VMID or tag.
      if (this.byTag) {
        this.value.templateVmid = '';
        this.value.templateTagMatch = this.value.templateTagMatch || 'subset';
      } else {
        this.value.templateTag = '';
        this.value.templateTagMatch = '';
      }

      // Full-clone-only in PVE, same reasoning as the watcher above.
      if (!this.cloneTargetEnabled) {
        this.value.cloneStorage = '';
        this.value.cloneFormat = '';
      }

      // Only once the node list has loaded: in degraded mode nothing was
      // fetched, and dropping a valid HA setting because an API call failed
      // would be worse than leaving it alone. The group follows the checkbox
      // because the driver rejects a group with HA off.
      if (this.nodes.options.length && !this.haAvailable) {
        this.value.ha = false;
      }
      if (!this.value.ha) {
        this.value.haGroup = '';
      }

      // In degraded mode the inputs are bound to `value` directly and the
      // selects hold nothing, so copying them across would wipe what was typed.
      if (!this.degraded) {
        // Syncs the form values into the bound machine-config object.
        this.value.node         = this.nodes.selected || '';
        this.value.netBridge    = this.bridges.selected || '';

        if (!this.byTag) {
          this.value.templateVmid = this.templates.selected ?? this.value?.templateVmid ?? '';
        }
      }

      this.stringifyScalars();
    },

    /**
     * Coerce the machine config to the types its CRD actually declares.
     *
     * Rancher generates that CRD from the driver's flags, and the mapping is
     * not uniform — confirmed by the two rejections it produces:
     *
     *   mcnflag.IntFlag  -> string   `templateVmid must be of type string: "integer"`
     *   mcnflag.BoolFlag -> boolean  `cloudinit must be of type boolean: "string"`
     *
     * So a number input binding a real number is rejected, and so is a
     * checkbox coerced to "true". Fixing it once on the way out is more
     * reliable than getting every individual binding right.
     *
     * `dataDisk` and `extraConfig` are in neither list on purpose: both are
     * already arrays of strings, which is what the CRD expects.
     *
     * To re-check the real types after a flag change:
     *   kubectl get crd pveconfigs.rke-machine-config.cattle.io -o json \
     *     | jq -r '.spec.versions[0].schema.openAPIV3Schema.properties
     *              | to_entries[] | "\(.key)\t\(.value.type)"'
     */
    stringifyScalars() {
      // Explicit lists rather than every key of `value`: the bound object is a
      // Steve resource that also carries metadata, links and actions, and
      // rewriting those would be at best pointless and at worst destructive.
      const booleanFields = [
        'cloudinit', 'onboot', 'skipPermissionCheck', 'keepOnFailure', 'linkedClone',
        'ha',
      ];

      const stringFields = [
        'node', 'allowedNodes', 'haGroup', 'tags', 'description', 'vmid', 'vmidRange',
        'templateVmid', 'templateTag', 'templateTagMatch',
        'cloneStorage', 'cloneFormat', 'vmNamePrefix',
        'cores', 'sockets', 'memory',
        'bootDiskSize', 'bootDiskDevice', 'backup', 'diskSetupTimeout', 'provisionDelay',
        'netIface', 'netDevice', 'netBridge', 'netModel',
        'netVlanTag', 'netMtu', 'netFirewall', 'agentTimeout', 'cloudinitTimeout',
        'ciuser', 'sshkeys', 'cicustom',
        'sshUser', 'sshPort',
        'ipMode', 'ipStart', 'ipEnd', 'ipPrefix', 'gateway', 'nameservers', 'searchdomain',
      ];

      booleanFields.forEach((key) => {
        const v = this.value?.[key];

        if (v === undefined) {
          return;
        }

        // A config saved by an older build may hold the string "false", and
        // !!'false' is true — so parse strings rather than test truthiness.
        this.value[key] = typeof v === 'string' ? v === 'true' : !!v;
      });

      stringFields.forEach((key) => {
        const v = this.value?.[key];

        if (v === undefined) {
          return;
        }

        this.value[key] = v === null ? '' : String(v);
      });
    },
  },
};
